import {esc,icon,btn,field,select} from './views.js';
import {money} from './core.js';
import {alerts,totals,salePreview} from './workshop.js';
const signed=(n,c)=>new Intl.NumberFormat('es-MX',{style:'currency',currency:c}).format(n);
export function posPage(s,u){const t=totals(s),low=alerts(s),cash=v=>signed(v,s.currency);
 return `<div class="page-heading"><div><div class="eyebrow">INVENTARIO Y MOVIMIENTOS LOCALES</div><h1>Punto de venta.</h1><p>Cada pedido, cada bobina y cada compra en su lugar.</p></div><div class="heading-actions">${btn('Registrar compra','purchase','plus')}${btn('Nueva venta','new-sale','calculator','primary')}</div></div>
 <div class="pos-stats">${[['Ventas cobradas',t.sales],['Compras de reposición',t.purchases],['Saldo · ventas − compras',t.balance],['Utilidad estimada de ventas',t.profit]].map(([l,v])=>`<div class="panel"><span class="small muted">${l}</span><strong class="stat-amount ${v<0?'danger-text':''}">${cash(v)}</strong></div>`).join('')}</div>
 <p class="short-note">Saldo: entradas por ventas menos compras registradas. Utilidad estimada: ventas menos costos calculados (material, luz, desgaste, repuestos, error, trabajo e insumos). Son dos medidas distintas; las compras no se descuentan dos veces. Totales en ${esc(s.currency)}, sin impuestos.</p>
 ${low.length?`<div class="stock-alert"><div class="between"><h3>${icon('spool')} Necesitas reponer ${low.length} artículo(s)</h3>${btn('Registrar reposición','purchase','plus','small')}</div><div class="alert-chips">${low.map(m=>`<span><b>${esc(m.name)}</b> · ${Number(m.stock.toFixed(2))} ${esc(m.unit)} ${m.stock<=0?'· AGOTADO':''}</span>`).join('')}</div></div>`:'<div class="hint-strip">Todo el inventario está por encima de sus avisos mínimos.</div>'}
 <div class="section-header section-space"><div><h3>Insumos compartidos entre pedidos</h3><p class="short-note">Registra paquetes completos y asigna cuántas unidades usa cada objeto en su calculadora.</p></div>${btn('Nuevo insumo','new-supply','plus')}</div>
 <div class="table-wrap"><table><thead><tr><th>Insumo</th><th>Existencias</th><th>Aviso mínimo</th><th>Costo / unidad</th><th>Paquete</th><th></th></tr></thead><tbody>${s.supplies.filter(m=>!m.retired).map(m=>`<tr><td><b>${esc(m.name)}</b></td><td class="${m.stock<=m.minStock?'danger-text':''}">${Number(m.stock.toFixed(2))} ${esc(m.unit)}</td><td>${m.minStock}</td><td>${cash(m.unitCost)}</td><td>${m.packUnits} ${esc(m.unit)}</td><td><div class="flex">${btn('Editar','edit-supply','edit','small',`data-id="${esc(m.id)}"`)}${btn('Comprar','purchase','','small',`data-kind="supply" data-id="${esc(m.id)}"`)}${btn('Eliminar','delete-supply','trash','small danger',`data-id="${esc(m.id)}"`)}</div></td></tr>`).join('')||'<tr><td colspan="6">Agrega argollas, imanes, empaques, pintura o pegamento. Puedes usar pzas, g, ml o m.</td></tr>'}</tbody></table></div>
 <div class="section-header section-space"><h3>Historial de ventas y compras</h3>${btn('Exportar movimientos CSV','export-ledger','download','small')}</div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Movimiento</th><th>Detalle</th><th>Importe</th><th></th></tr></thead><tbody>${s.ledger.slice().reverse().map(t=>`<tr class="${t.voided?'voided':''}"><td>${new Date(t.date).toLocaleString('es-MX')}</td><td><span class="badge ${t.type==='purchase'?'outline':''}">${t.voided?'Anulado':t.type==='sale'?'Venta':'Compra'}</span></td><td class="wrap">${esc(t.type==='sale'?t.lines.map(l=>`${l.qty} × ${l.name}`).join(' · '):t.movements.map(m=>`${Number(m.units.toFixed(2))} ${m.unit} · ${m.name}`).join(' · '))}${t.note?`<p class="small muted">${esc(t.note)}</p>`:''}</td><td>${signed(t.total,t.currency)}</td><td>${t.voided?'—':btn('Anular','void-transaction','back','small',`data-id="${esc(t.id)}"`)}</td></tr>`).join('')||'<tr><td colspan="5">Al confirmar una venta se descuenta su material. Cotizar no modifica el inventario.</td></tr>'}</tbody></table></div>
 ${[...s.materials,...s.supplies].some(x=>x.retired)?`<details class="panel section-space"><summary>Artículos retirados con historial</summary>${[...s.materials.map(m=>({...m,kind:'material'})),...s.supplies.map(m=>({...m,kind:'supply'}))].filter(m=>m.retired).map(m=>`<div class="between cost-row">${esc(m.name)}${btn('Restaurar','restore-stock','','small',`data-kind="${m.kind}" data-id="${esc(m.id)}"`)}</div>`).join('')}</details>`:''}`;
}
export function printerPanel(s,u){const p=s.printers.find(p=>p.id===s.activePrinterId);return `<div class="section-header"><h3>Mis impresoras</h3><div class="flex">${btn('Comprobar ahora','probe-printers','refresh','small')}${btn('Agregar impresora','new-printer','plus','primary')}</div></div><div class="printer-grid">${s.printers.map(p=>`<div class="panel ${p.id===s.activePrinterId?'active-profile':''}"><div class="between"><h3>${esc(p.printer)}</h3>${p.id===s.activePrinterId?'<span class="badge">Activa</span>':''}</div><p class="device-status" data-printer-status="${esc(p.id)}">${esc(u.printerStatus?.[p.id]?.message||'Sin comprobar')}</p><p class="short-note">${p.bedX} × ${p.bedY} × ${p.bedZ} mm</p><div class="flex">${btn(p.id===s.activePrinterId?'Perfil en edición':'Usar y editar','use-printer','check','small',`data-id="${esc(p.id)}"`)}${btn('Eliminar','delete-printer','trash','small danger',`data-id="${esc(p.id)}"`)}</div></div>`).join('')}</div>
 ${p?`<div class="panel section-space"><div class="section-header"><h3>Conexión de ${esc(p.printer)}</h3><span class="badge outline">Comprobación cada 5 s</span></div><div class="form-grid">${select('Tipo de conexión',[['none','Sin conexión configurada'],['usb','Cable USB / puerto serie'],['network','Red local · IP o nombre del equipo']],p.connection,'data-connection="connection"')}${p.connection==='usb'?select('Dispositivo de Windows',[['','Elige el dispositivo conectado'],...(u.devices||[]).map(d=>[d.id,`${d.name} ${d.port||''}`]),...(!(u.devices||[]).some(d=>d.id===p.deviceId)&&p.deviceId?[[p.deviceId,'Dispositivo guardado · desconectado']]:[])],p.deviceId,'data-connection="deviceId"'):p.connection==='network'?field('IP o nombre (sin http://)',p.host,'data-connection="host"','text')+field('Puerto del servicio',p.port,'data-connection="port" min="1" max="65535" step="1"'):''}</div><p class="short-note" id="printer-probe-note">USB detecta la presencia del dispositivo asociado sin ocupar el puerto de Cura. Red comprueba el puerto que configures. Estar conectado no confirma que la impresora esté lista, imprimiendo o sea el modelo elegido. La primera vez debes asociar el dispositivo; no todas las impresoras identifican su modelo.</p><p class="small muted" data-probe-time>${esc(u.probeTime||'Pendiente de comprobación')}</p></div>`:''}`;}
export function saleBody(s,u){let p,error;try{p=salePreview(s,u.cart,u.saleReserve!==false);}catch(e){error=e.message;}
 const objects=s.boxes.filter(b=>!b.archived).flatMap(b=>b.objects.map(o=>[`${b.id}|${o.id}`,`${b.name} · ${o.name}`]));
 return `<div class="form-grid">${select('Objeto',objects,objects[0]?.[0],'id="sale-object"')}${field('Cantidad',1,'id="sale-qty" min="1" step="1"')}</div><div class="section-space">${btn('Agregar al pedido','add-sale-line','plus','small')}</div>
 <div class="table-wrap section-space"><table><thead><tr><th>Objeto</th><th>Cantidad</th><th>Venta / unidad</th><th></th></tr></thead><tbody>${u.cart.map((l,i)=>`<tr><td>${esc(l.name)}</td><td>${l.qty}</td><td><input class="table-input" type="number" min="0" step=".01" value="${l.unitPrice}" data-sale-price="${i}"></td><td>${btn('Quitar','remove-sale-line','trash','small',`data-index="${i}"`)}</td></tr>`).join('')}</tbody></table></div>
 <label class="field inline section-space"><input type="checkbox" id="sale-reserve" ${u.saleReserve!==false?'checked':''}> Descontar también el ${s.settings.error}% de reserva de filamento</label>
 ${p?`<div class="section-header section-space"><h3>Total a cobrar</h3><strong>${money(p.total,s.currency)}</strong></div><h3>Material que se descontará</h3><div class="table-wrap"><table><thead><tr><th>Artículo</th><th>Pedido</th><th>Disponible</th><th>Falta</th></tr></thead><tbody>${p.movements.map(m=>`<tr class="${m.shortage>1e-6?'danger-text':''}"><td>${esc(m.name)}</td><td>${m.units.toFixed(2)} ${esc(m.unit)}</td><td>${m.available.toFixed(2)}</td><td>${m.shortage.toFixed(2)}</td></tr>`).join('')}</tbody></table></div>${p.shortages.length?'<p class="danger-text">Repón los artículos faltantes antes de confirmar.</p>':''}`:`<p class="short-note">${esc(error)}</p>`}
 ${field('Referencia / cliente / nota',u.saleNote||'','id="sale-note"','text')}<p class="short-note">Registra un pedido vendido una sola vez. Confirmar descuenta los materiales, registra el cobro y guarda los costos de ese momento. No procesa pagos ni controla la impresión.</p>`;
}
